using System.IdentityModel.Tokens.Jwt;using MediDesk.Api.Authorization;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace MediDesk.Api.Controllers{[ApiController][Route("api/stores")][Authorize(Policy=PermissionPolicies.StoresView)]public sealed class StoresController(IStoreService s):ControllerBase{[HttpGet]public async Task<ActionResult<PagedResponse<StoreDto>>>Get([FromQuery]StoreQuery q,CancellationToken ct)=>Ok(await s.GetPageAsync(q,ct));[HttpPost][Authorize(Policy=PermissionPolicies.StoresAdd)]public async Task<ActionResult<StoreDto>>Create(CreateStoreRequest r,CancellationToken ct)=>Ok(await s.CreateAsync(r,long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value),ct));}}

